1	/**
2	 * Article ref minting per ADR-0004.
3	 *
4	 * An article has exactly one public identity: art-<yyyymmdd>-<hex8>, minted
5	 * once by Feed at first acquisition. It carries no publisher, title, or URL
6	 * semantics: the date segment is only the UTC calendar date of the
7	 * acquisition timestamp (extracted_at), and the hex segment is 8 random
8	 * lowercase hex characters. Only Feed mints refs; this module is the only
9	 * place that does.
10	 */
11	
12	import { randomBytes } from 'crypto';
13	
14	const ARTICLE_REF_PATTERN = /^art-\d{8}-[0-9a-f]{8}$/;
15	
16	/** Mint a new opaque article ref. `extractedAtIso` should be the article's own extracted_at. */
17	export function mintArticleRef(extractedAtIso: string): string {
18	  const parsed = new Date(extractedAtIso);
19	  const dateForRef = Number.isNaN(parsed.getTime()) ? new Date() : parsed;
20	  const yyyymmdd = dateForRef.toISOString().slice(0, 10).replace(/-/g, '');
21	  const hex8 = randomBytes(4).toString('hex');
22	  return `art-${yyyymmdd}-${hex8}`;
23	}
